%% ============================================================
% FUNCTION 1:
% 1-D 5/3 DWT
%
% High-pass:
%
% H[n] = -x[2n-1]
%        +2*x[2n]
%        -x[2n+1]
%
%
% Low-pass:
%
% L[n] = -x[2n-1]
%        +2*x[2n]
%        +6*x[2n+1]
%        +2*x[2n+2]
%        -x[2n+3]
%
% Boundary convention:
%
% x[-1] = x[1]
% x[N]  = x[N-2]
% x[N+1] = x[N-3]
%
% ============================================================

function [H,L] = dwt53_1d(x)

    N = length(x);

    if mod(N,2) ~= 0

        error('DWT input length must be even.');

    end

    HALF = N/2;

    H = zeros(1,HALF);

    L = zeros(1,HALF);


    for n = 0:HALF-1

        % ----------------------------------------------------
        % HIGH-PASS
        % ----------------------------------------------------

        % x[2n-1]
        if n == 0

            xm1 = x(2);

        else

            xm1 = x(2*n);

        end


        % x[2n]
        x0 = x(2*n + 1);


        % x[2n+1]
        if (2*n + 1) >= N

            xp1 = x(N-1);

        else

            xp1 = x(2*n + 2);

        end


        H(n+1) = ...
            -xm1 ...
            +2*x0 ...
            -xp1;


        % ----------------------------------------------------
        % LOW-PASS
        % ----------------------------------------------------

        % x[2n-1]
        if n == 0

            xm1 = x(3);

        else

            xm1 = x(2*n);

        end


        % x[2n]
        x0 = x(2*n + 1);


        % x[2n+1]
        xp1 = x(2*n + 2);


        % x[2n+2]
        if (2*n + 2) >= N

            xp2 = x(N-1);

        else

            xp2 = x(2*n + 3);

        end


        % x[2n+3]
        if (2*n + 3) >= N

            xp3 = x(N-2);

        else

            xp3 = x(2*n + 4);

        end


        L(n+1) = ...
            -xm1 ...
            +2*x0 ...
            +6*xp1 ...
            +2*xp2 ...
            -xp3;

    end

end


%% ============================================================
% FUNCTION 2:
% READ SIGNED HEX
%
% bits = 16 for:
%   H, L, HH, HL, LH
%
% bits = 17 for:
%   LL
%
% ============================================================

function y = read_signed_hex(filename,bits)

    fid = fopen(filename,'r');

    if fid == -1

        error('Could not open file: %s',filename);

    end


    data = textscan(fid,'%s');

    fclose(fid);


    hex_data = data{1};


    % HEX → unsigned value

    u = hex2dec(hex_data);


    % Two's-complement conversion

    threshold = 2^(bits-1);

    modulus = 2^bits;


    u(u >= threshold) = ...
        u(u >= threshold) - modulus;


    y = double(u);

    y = y(:);

end